  function addViewComposerColumnRow() {
    var body = document.getElementById('cmdp-view-column-rows');
    var spec = state.selectedTemplate && state.selectedTemplate.spec ? state.selectedTemplate.spec : defaultSpec();
    var sourceAlias = finalBaseResultAlias(spec) || readValue('cmdp-view-source') || (state.viewComposerDraft && state.viewComposerDraft.sourceAlias) || '';
    if (body) body.insertAdjacentHTML('beforeend', renderViewComposerColumnRow({}, spec, sourceAlias));
  }

  function viewComposerColumnRowHasValue(row) {
    if (!row) return false;
    var field = row.querySelector('[data-view-column-field="field"]');
    var title = row.querySelector('[data-view-column-field="title"]');
    return Boolean(String(field && field.value || '').trim() || String(title && title.value || '').trim());
  }

  function ensureTrailingViewComposerColumnRow(target) {
    if (!target || !target.closest) return;
    var body = document.getElementById('cmdp-view-column-rows');
    var row = target.closest('[data-view-column-row]');
    if (!body || !row || !body.contains(row)) return;
    var rows = Array.prototype.slice.call(body.querySelectorAll('[data-view-column-row]'));
    if (!rows.length || rows[rows.length - 1] !== row) return;
    if (!viewComposerColumnRowHasValue(row)) return;
    addViewComposerColumnRow();
  }

  function clearViewComposerColumnRow(button) {
    var row = button && button.closest ? button.closest('[data-view-column-row]') : null;
    if (!row) return;
    row.querySelectorAll('input').forEach(function (field) {
      field.value = '';
    });
    row.querySelectorAll('select').forEach(function (field) {
      field.value = '';
    });
  }

  function diagramMappingKindFromElement(element) {
    return String(element && element.getAttribute && element.getAttribute('data-diagram-mapping-kind') || '').trim();
  }

  function diagramMappingRowHasDomValue(row) {
    if (!row) return false;
    var source = row.querySelector('[data-diagram-mapping-field="from"]');
    if (source && String(source.value || '').trim()) return true;
    var type = row.querySelector('[data-diagram-mapping-field="type"]');
    return Boolean(type && String(type.value || '').trim() && String(type.value || '').trim() !== 'generic');
  }

  function reindexDiagramMappingRows(body) {
    Array.prototype.slice.call((body || document).querySelectorAll('[data-diagram-mapping-row]')).forEach(function (row, index) {
      row.setAttribute('data-diagram-mapping-index', String(index));
      if (row.nextElementSibling && row.nextElementSibling.hasAttribute('data-diagram-mapping-detail')) {
        row.nextElementSibling.setAttribute('data-diagram-mapping-index', String(index));
      }
    });
  }

  function insertDiagramTemplateToken(button) {
    var token = String(button && button.getAttribute('data-template-token') || '').trim();
    var detailRow = button && button.closest ? button.closest('[data-diagram-mapping-detail]') : null;
    var roleMapping = button && button.closest ? button.closest('[data-diagram-import-role-mapping]') : null;
    var input = detailRow
      ? detailRow.querySelector('[data-diagram-mapping-field="labelTemplate"]')
      : roleMapping
        ? roleMapping.querySelector('[data-diagram-import-role-field="primary.labelTemplate"]')
        : null;
    if (!token || !input) return;
    var text = '$' + '{' + token + '}';
    var start = Number.isInteger(input.selectionStart) ? input.selectionStart : String(input.value || '').length;
    var end = Number.isInteger(input.selectionEnd) ? input.selectionEnd : start;
    input.value = String(input.value || '').slice(0, start) + text + String(input.value || '').slice(end);
    input.focus();
    if (input.setSelectionRange) input.setSelectionRange(start + text.length, start + text.length);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function addDiagramMappingRow(button) {
    var kind = diagramMappingKindFromElement(button);
    var body = document.querySelector('[data-diagram-mapping-body][data-diagram-mapping-kind="' + kind + '"]');
    if (!kind || !body) return;
    markImportedDiagramChanged();
    var rows = Array.prototype.slice.call(body.querySelectorAll('[data-diagram-mapping-row]'));
    body.insertAdjacentHTML('beforeend', renderDiagramMappingRow(kind, {}, rows.length, state.selectedTemplate && state.selectedTemplate.spec || defaultSpec()));
  }

  function clearDiagramMappingRow(button) {
    var row = button && button.closest ? button.closest('[data-diagram-mapping-row]') : null;
    var body = row && row.parentElement;
    if (!row || !body) return;
    markImportedDiagramChanged();
    var rows = Array.prototype.slice.call(body.querySelectorAll('[data-diagram-mapping-row]'));
    if (rows.length > 1) {
      var detailRow = row.nextElementSibling && row.nextElementSibling.hasAttribute('data-diagram-mapping-detail') ? row.nextElementSibling : null;
      row.remove();
      if (detailRow) detailRow.remove();
      reindexDiagramMappingRows(body);
      return;
    }
    row.querySelectorAll('input,select').forEach(function (field) {
      if (field.type === 'checkbox') field.checked = field.getAttribute('data-diagram-mapping-field') === 'dataIncludeSourceRef';
      else field.value = field.getAttribute('data-diagram-mapping-field') === 'type' ? 'generic' : '';
    });
    if (row.nextElementSibling && row.nextElementSibling.hasAttribute('data-diagram-mapping-detail')) {
      row.nextElementSibling.querySelectorAll('input,select').forEach(function (field) {
        if (field.type === 'checkbox') field.checked = field.getAttribute('data-diagram-mapping-field') === 'dataIncludeSourceRef';
        else field.value = '';
      });
    }
  }

  function ensureTrailingDiagramMappingRow(target) {
    if (!target || !target.closest) return;
    var row = target.closest('[data-diagram-mapping-row]');
    var body = row && row.parentElement;
    if (!row || !body) return;
    var rows = Array.prototype.slice.call(body.querySelectorAll('[data-diagram-mapping-row]'));
    if (!rows.length || rows[rows.length - 1] !== row) return;
    if (!diagramMappingRowHasDomValue(row)) return;
    var kind = diagramMappingKindFromElement(row);
    body.insertAdjacentHTML('beforeend', renderDiagramMappingRow(kind, {}, rows.length, state.selectedTemplate && state.selectedTemplate.spec || defaultSpec()));
  }

  function diagramImportSelectedValues(field) {
    if (!field) return [];
    if (field.multiple) {
      return Array.prototype.slice.call(field.options || []).filter(function (option) { return option.selected; }).map(function (option) {
        return String(option.value || '').trim();
      }).filter(Boolean);
    }
    return splitToolList(String(field.value || ''));
  }

  function captureDiagramImportProposalFromDom(manualBindingId) {
    var proposal = state.diagramImportProposal;
    if (!proposal) return proposal;
    if (proposal.version === 3) {
      var roleMappingVisible = Boolean(document.querySelector('[data-diagram-import-role-mapping]'));
      if (roleMappingVisible) (Array.isArray(proposal.roles) ? proposal.roles : []).forEach(function (role) {
        var semanticField = document.querySelector('[data-diagram-import-semantic="' + String(role.id || '').replace(/"/g, '\\"') + '"]');
        if (semanticField) role.selectedSemantic = String(semanticField.value || '').trim();
        var exemplarField = document.querySelector('[data-diagram-import-exemplar="' + String(role.id || '').replace(/"/g, '\\"') + '"]');
        if (exemplarField) role.exemplarKey = String(exemplarField.value || '').trim();
        var container = document.querySelector('[data-diagram-import-role-mapping="' + String(role.id || '').replace(/"/g, '\\"') + '"]');
        if (!container) return;
        var value = function (name) {
          var field = container.querySelector('[data-diagram-import-role-field="' + name + '"]');
          return String(field && field.value || '').trim();
        };
        var primary = role.mapping && role.mapping.primary || {};
        var sourceStageId = value('source.stageId');
        var sourceStage = diagramImportStageById(state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(), sourceStageId);
        primary.className = value('primary.className') || sourceStage && sourceStage.className || '';
        primary.idAttribute = value('primary.idAttribute') || '_id';
        primary.labelTemplate = value('primary.labelTemplate') || '\${Description}';
        primary.structuredFields = diagramImportSelectedValues(container.querySelector('[data-diagram-import-role-field="primary.structuredFields"]'));
        var filterPath = value('primary.filter.path');
        var filterValue = value('primary.filter.value');
        primary.filters = filterPath && filterValue ? [{ path: filterPath, op: value('primary.filter.op') || 'equals', value: filterValue }] : [];
        role.mapping = role.mapping || {};
        role.mapping.source = sourceStageId ? {
          stageId: sourceStageId,
          alias: sourceStage && sourceStage.alias || '',
          kind: sourceStage && sourceStage.kind || '',
          className: sourceStage && sourceStage.className || ''
        } : {};
        role.mapping.primary = primary;
        role.mapping.related = Array.prototype.slice.call(container.querySelectorAll('[data-diagram-import-related-row]')).map(function (row, index) {
          var field = function (name) { return row.querySelector('[data-diagram-import-related-field="' + name + '"]'); };
          var pathField = field('path');
          var option = pathField && pathField.options[pathField.selectedIndex];
          var className = String(field('className') && field('className').value || '').trim();
          var direction = String(field('direction') && field('direction').value || 'both');
          return {
            id: role.mapping.related[index] && role.mapping.related[index].id || 'related_' + String(index + 1),
            className: className,
            path: diagramImportPathFromOption(option, direction),
            structuredFields: diagramImportSelectedValues(field('structuredFields'))
          };
        }).filter(function (item) { return item.className || item.path.length || item.structuredFields.length; });
      });
      var relationRuleRows = Array.prototype.slice.call(document.querySelectorAll('[data-diagram-import-rule-row]'));
      if (relationRuleRows.length) proposal.relationRules = relationRuleRows.map(function (row, index) {
        var field = function (name) { return row.querySelector('[data-diagram-import-rule-field="' + name + '"]'); };
        var pathField = field('path');
        var option = pathField && pathField.options[pathField.selectedIndex];
        var direction = String(field('direction') && field('direction').value || 'both');
        return {
          id: proposal.relationRules[index] && proposal.relationRules[index].id || 'relation_rule_' + String(index + 1),
          kind: String(field('kind') && field('kind').value || 'connection'),
          parentRoleId: String(field('parentRoleId') && field('parentRoleId').value || ''),
          childRoleId: String(field('childRoleId') && field('childRoleId').value || ''),
          path: diagramImportPathFromOption(option, direction)
        };
      });
      var placementRuleRows = Array.prototype.slice.call(document.querySelectorAll('[data-diagram-import-placement-row]'));
      if (placementRuleRows.length) proposal.placementRules = placementRuleRows.map(function (row, index) {
        var field = function (name) { return row.querySelector('[data-diagram-import-placement-field="' + name + '"]'); };
        return {
          id: proposal.placementRules[index] && proposal.placementRules[index].id || 'placement_rule_' + String(index + 1),
          parentRoleId: String(field('parentRoleId') && field('parentRoleId').value || ''),
          childRoleId: String(field('childRoleId') && field('childRoleId').value || '')
        };
      }).filter(function (rule) { return rule.parentRoleId || rule.childRoleId; });
      refreshDiagramImportSemanticState(proposal);
      state.diagramImportProposal = proposal;
      var sourceV3 = document.getElementById('cmdp-diagram-import-source');
      if (sourceV3) state.diagramImportSource = sourceV3.value;
      return proposal;
    }
    if (!Array.isArray(proposal.bindings)) return proposal;
    (Array.isArray(proposal.containerRoles) ? proposal.containerRoles : []).forEach(function (role) {
      var field = document.querySelector('[data-diagram-import-semantic="' + String(role.key || '').replace(/"/g, '\\"') + '"]');
      if (field) role.selectedRole = String(field.value || '').trim();
    });
    refreshDiagramImportSemanticState(proposal);
    var spec = state.selectedTemplate && state.selectedTemplate.spec || defaultSpec();
    proposal.bindings.forEach(function (binding) {
      var row = document.querySelector('[data-diagram-import-binding-row="' + binding.id + '"]');
      if (!row) return;
      var mapping = cloneJsonValue(binding.mapping || {}, {});
      mapping.fields = mapping.fields && typeof mapping.fields === 'object' && !Array.isArray(mapping.fields) ? mapping.fields : {};
      var previousSource = String(mapping.from || '').trim();
      Array.prototype.slice.call(row.querySelectorAll('[data-diagram-import-field]')).forEach(function (field) {
        var name = String(field.getAttribute('data-diagram-import-field') || '').trim();
        if (name === 'remove') {
          binding.remove = Boolean(field.checked);
          return;
        }
        var value = String(field.value || '').trim();
        if (name === 'from') mapping.from = value;
        else if (value) mapping.fields[name] = value;
        else delete mapping.fields[name];
      });
      if (mapping.from && mapping.from !== previousSource) {
        var allowedFields = matchingColumnOptionRowsForOutput(spec, mapping.from).map(function (item) { return item && item.value; }).filter(Boolean);
        Object.keys(mapping.fields).forEach(function (name) {
          if (allowedFields.indexOf(mapping.fields[name]) === -1) delete mapping.fields[name];
        });
      }
      binding.mapping = mapping;
      binding.unresolved = binding.remove || binding.active === false ? [] : (mapping.from ? [] : ['from']);
      var requiredFields = binding.family === 'edgeMappings'
        ? ['source', 'target']
        : binding.family === 'hierarchyMappings'
          ? ['child', 'parent']
          : ['id'];
      requiredFields.forEach(function (name) {
        if (binding.active !== false && !binding.remove && !String(mapping.fields[name] || '').trim()) binding.unresolved.push(name);
      });
      if (mapping.from && (binding.confidence === 'none' || String(binding.id) === String(manualBindingId || ''))) binding.confidence = 'manual';
    });
    refreshDiagramImportSemanticState(proposal);
    state.diagramImportProposal = proposal;
    var source = document.getElementById('cmdp-diagram-import-source');
    if (source) state.diagramImportSource = source.value;
    return proposal;
  }

  function diagramImportBindingOverrides(proposal) {
    if (proposal && proposal.version === 3) {
      return (proposal.roles || []).map(function (role) {
        return {
          id: role.id,
          selectedSemantic: role.selectedSemantic,
          exemplarKey: role.exemplarKey,
          mapping: cloneJsonValue(role.mapping || {}, {})
        };
      });
    }
    return (proposal && Array.isArray(proposal.bindings) ? proposal.bindings : []).map(function (binding) {
      return {
        id: binding.id,
        mapping: cloneJsonValue(binding.mapping || {}, {}),
        remove: binding.remove === true,
        confidence: binding.confidence === 'manual' ? 'manual' : binding.confidence
      };
    });
  }

  function diagramImportSemanticOverrides(proposal) {
    return (proposal && Array.isArray(proposal.containerRoles) ? proposal.containerRoles : []).map(function (role) {
      return { key: String(role.key || ''), semantic: String(role.selectedRole || '') };
    });
  }

  function acceptDiagramImportBinding(button) {
    if (state.diagramImportBusy || state.diagramImportAssistantBusy) return;
    var id = String(button && button.getAttribute('data-binding-id') || '').trim();
    var proposal = captureDiagramImportProposalFromDom(id);
    var binding = proposal && proposal.bindings && proposal.bindings.find(function (item) { return String(item.id) === id; });
    if (binding && !binding.remove && binding.mapping && binding.mapping.from) binding.confidence = 'manual';
    renderDesigner();
  }

  function mutateDiagramImportV3(action, target) {
    var proposal = captureDiagramImportProposalFromDom();
    if (!proposal || proposal.version !== 3) return;
    if (action === 'diagram-import-add-related') {
      var container = target.closest('[data-diagram-import-role-mapping]');
      var roleId = String(container && container.getAttribute('data-diagram-import-role-mapping') || '');
      var role = (proposal.roles || []).find(function (item) { return String(item.id) === roleId; });
      if (role) {
        role.mapping.related = Array.isArray(role.mapping.related) ? role.mapping.related : [];
        role.mapping.related.push({ id: 'related_' + Date.now(), className: '', path: [], structuredFields: ['Code', 'Description'] });
      }
    } else if (action === 'diagram-import-remove-related') {
      var relatedContainer = target.closest('[data-diagram-import-role-mapping]');
      var relatedRoleId = String(relatedContainer && relatedContainer.getAttribute('data-diagram-import-role-mapping') || '');
      var relatedRole = (proposal.roles || []).find(function (item) { return String(item.id) === relatedRoleId; });
      var relatedRow = target.closest('[data-diagram-import-related-row]');
      var relatedIndex = Number(relatedRow && relatedRow.getAttribute('data-diagram-import-related-row'));
      if (relatedRole && Number.isInteger(relatedIndex)) relatedRole.mapping.related.splice(relatedIndex, 1);
    } else if (action === 'diagram-import-add-rule') {
      proposal.relationRules = Array.isArray(proposal.relationRules) ? proposal.relationRules : [];
      proposal.relationRules.push({ id: 'relation_rule_' + Date.now(), kind: 'connection', parentRoleId: '', childRoleId: '', path: [] });
    } else if (action === 'diagram-import-remove-rule') {
      var ruleRow = target.closest('[data-diagram-import-rule-row]');
      var ruleIndex = Number(ruleRow && ruleRow.getAttribute('data-diagram-import-rule-row'));
      if (Number.isInteger(ruleIndex)) proposal.relationRules.splice(ruleIndex, 1);
    } else if (action === 'diagram-import-add-placement') {
      proposal.placementRules = Array.isArray(proposal.placementRules) ? proposal.placementRules : [];
      proposal.placementRules.push({ id: 'placement_rule_' + Date.now(), parentRoleId: '', childRoleId: '' });
    } else if (action === 'diagram-import-remove-placement') {
      var placementRow = target.closest('[data-diagram-import-placement-row]');
      var placementIndex = Number(placementRow && placementRow.getAttribute('data-diagram-import-placement-row'));
      if (Number.isInteger(placementIndex)) proposal.placementRules.splice(placementIndex, 1);
    }
    refreshDiagramImportSemanticState(proposal);
    renderDesigner();
  }

  function diagramImportProposalHasReviewBlocker(proposal) {
    refreshDiagramImportSemanticState(proposal);
    if (proposal && proposal.version === 3) return state.diagramImportStale || Boolean((proposal.unresolved || []).length);
    var bindings = proposal && Array.isArray(proposal.bindings) ? proposal.bindings : [];
    return state.diagramImportStale || (proposal.unresolved || []).some(function (item) { return item && item.family === 'containerRoles'; }) || bindings.some(function (binding) {
      return binding && binding.active !== false && !binding.remove && ((binding.unresolved && binding.unresolved.length) || binding.confidence === 'ambiguous');
    });
  }

  function persistedDiagramImportSource() {
    var diagram = firstDiagramSpec(state.selectedTemplate && state.selectedTemplate.spec || defaultSpec());
    var d2Import = diagram && diagram.authoring && diagram.authoring.d2Import;
    return String(d2Import && d2Import.source || '');
  }

  function markImportedDiagramChanged() {
    if (!persistedDiagramImportSource() && !state.diagramImportAppliedPendingPreview) return;
    state.lastDraftPreviewOk = false;
    state.diagramImportAppliedPendingPreview = true;
    syncImportedDiagramSaveGate();
  }

  function syncImportedDiagramSaveGate() {
    var blocked = Boolean(state.diagramImportProposal) || state.diagramImportStale || (state.diagramImportAppliedPendingPreview && !state.lastDraftPreviewOk);
    Array.prototype.slice.call(document.querySelectorAll('[data-action="save-template"]')).forEach(function (button) {
      button.disabled = blocked;
      button.setAttribute('aria-disabled', blocked ? 'true' : 'false');
      button.title = blocked
        ? t(state.diagramImportStale ? 'diagramImportStale' : state.diagramImportProposal ? 'diagramImportReviewBlocked' : 'diagramImportPreviewRequired')
        : '';
    });
  }

  function analyzeDiagramImport() {
    if (state.diagramImportBusy || state.diagramImportAssistantBusy) return;
    if (!captureVisibleDesignerState()) return;
    var source = document.getElementById('cmdp-diagram-import-source');
    state.diagramImportSource = String(source && source.value || state.diagramImportSource || '');
    if (!state.diagramImportSource.trim()) {
      state.message = { type: 'error', text: t('fieldRequired', { label: t('diagramImportSource') }) };
      renderDesigner();
      return;
    }
    state.diagramImportBusy = true;
    state.diagramImportProposal = null;
    state.diagramImportSignedProposal = null;
    state.diagramImportIr = null;
    state.diagramImportPreviewError = '';
    state.diagramImportStale = false;
    var requestTemplate = state.selectedTemplate;
    state.message = { type: 'ok', text: t('diagramImportAnalyzing') };
    renderDesigner();
    var requestSource = state.diagramImportSource;
    request(apiPrefix + '/draft/diagram-import/analyze', {
      method: 'POST',
      timeoutMs: 30000,
      body: {
        root: state.root,
        templateCode: state.selectedTemplate && state.selectedTemplate.code || '',
        baseSpecHash: state.selectedTemplate && state.selectedTemplate.specHash || '',
        currentSpec: state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(),
        d2Source: requestSource
      }
    }).then(function (result) {
      if (state.selectedTemplate !== requestTemplate) throw new Error(t('assistantResponseStale'));
      if (!result.ok || !result.json || !result.json.proposal) throw new Error(errorText(result));
      state.diagramImportSignedProposal = cloneJsonValue(result.json.proposal, null);
      state.diagramImportProposal = cloneJsonValue(result.json.proposal, null);
      state.diagramImportIr = result.json.ir || null;
      if (state.diagramImportSource === requestSource) {
        state.diagramImportPreview = cloneJsonValue(result.json.preview, null);
        state.diagramImportPreviewSource = requestSource;
        state.diagramImportPreviewError = '';
      }
      if (result.json.catalog) {
        var catalogRecord = { catalog: result.json.catalog, updatedAt: result.json.catalog.generatedAt || new Date().toISOString() };
        applyCatalogCache(catalogRecord);
        writeCatalogCache(result.json.catalog);
      }
      state.diagramImportStale = state.diagramImportSource !== requestSource;
      state.message = { type: state.diagramImportStale ? 'error' : 'ok', text: state.diagramImportStale ? t('diagramImportStale') : t('diagramImportReady') };
    }).catch(function (error) {
      var message = String(error && error.message || error || t('requestFailed')).slice(0, 500);
      state.diagramImportPreviewError = message;
      state.message = { type: 'error', text: message };
    }).finally(function () {
      state.diagramImportBusy = false;
      renderDesigner();
    });
  }

  function completeDiagramImportWithAssistant() {
    if (state.diagramImportBusy || state.diagramImportAssistantBusy) return;
    if (!captureVisibleDesignerState()) return;
    var proposal = captureDiagramImportProposalFromDom();
    if (!proposal) {
      state.message = { type: 'error', text: t('diagramImportNoProposal') };
      renderDesigner();
      return;
    }
    if (state.diagramImportStale) {
      state.message = { type: 'error', text: t('diagramImportStale') };
      renderDesigner();
      return;
    }
    state.diagramImportAssistantBusy = true;
    state.message = { type: 'ok', text: t('diagramImportAssistantRunning') };
    renderDesigner();
    var requestSource = state.diagramImportSource;
    request(apiPrefix + '/assistant/diagram-import/complete?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), {
      method: 'POST',
      timeoutMs: assistantRequestTimeoutMs(),
      body: {
        root: state.root,
        currentSpec: state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(),
        proposal: state.diagramImportSignedProposal,
        roles: diagramImportBindingOverrides(proposal),
        relationRules: cloneJsonValue(proposal.relationRules || [], []),
        placementRules: cloneJsonValue(proposal.placementRules || [], [])
      }
    }).then(function (result) {
      if (!result.ok || !result.json || !result.json.proposal) throw new Error(errorText(result));
      state.diagramImportSignedProposal = cloneJsonValue(result.json.proposal, null);
      state.diagramImportProposal = cloneJsonValue(result.json.proposal, null);
      state.diagramImportStale = state.diagramImportSource !== requestSource;
      state.message = { type: state.diagramImportStale ? 'error' : 'ok', text: state.diagramImportStale ? t('diagramImportStale') : (result.json.explanation || t('diagramImportReady')) };
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      state.diagramImportAssistantBusy = false;
      renderDesigner();
    });
  }

  function applyDiagramImport() {
    if (state.diagramImportBusy || state.diagramImportAssistantBusy) return;
    if (!captureVisibleDesignerState()) return;
    var proposal = captureDiagramImportProposalFromDom();
    if (!proposal) {
      state.message = { type: 'error', text: t('diagramImportNoProposal') };
      renderDesigner();
      return;
    }
    if (diagramImportProposalHasReviewBlocker(proposal)) {
      state.message = { type: 'error', text: state.diagramImportStale ? t('diagramImportStale') : t('diagramImportReviewBlocked') };
      renderDesigner();
      return;
    }
    var requestTemplate = state.selectedTemplate;
    var requestSignedProposal = state.diagramImportSignedProposal;
    state.diagramImportBusy = true;
    renderDesigner();
    request(apiPrefix + '/draft/diagram-import/apply', {
      method: 'POST',
      timeoutMs: 30000,
      body: {
        root: state.root,
        currentSpec: state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(),
        proposal: state.diagramImportSignedProposal,
        roles: diagramImportBindingOverrides(proposal),
        relationRules: cloneJsonValue(proposal.relationRules || [], []),
        placementRules: cloneJsonValue(proposal.placementRules || [], [])
      }
    }).then(function (result) {
      if (state.selectedTemplate !== requestTemplate || state.diagramImportSignedProposal !== requestSignedProposal) throw new Error(t('assistantResponseStale'));
      if (!result.ok || !result.json || !result.json.spec) throw new Error(errorText(result));
      updateSelectedFromEditor(assistantSpecWithPrompts(result.json.spec));
    state.diagramImportProposal = null;
    state.diagramImportSignedProposal = null;
    state.diagramImportIr = null;
    state.diagramImportPreview = null;
    state.diagramImportPreviewSource = '';
    state.diagramImportPreviewError = '';
    state.lastDraftPreviewOk = false;
      state.diagramImportAppliedPendingPreview = true;
      state.diagramImportStale = false;
      state.message = { type: 'ok', text: t('diagramImportApplied') };
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      state.diagramImportBusy = false;
      renderDesigner();
    });
  }

  function refreshDiagramMappingEditorAfterSourceChange() {
    try {
      updateSelectedFromEditor(applyVisualizationToSpec(state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(), false));
      renderDesigner();
    } catch (error) {
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
    }
  }

  function refreshVisualizationRowGroupLabels(container) {
    Array.prototype.slice.call((container || document).querySelectorAll('[data-visualization-row-group]')).forEach(function (row, index) {
      var label = row.querySelector('[data-row-group-label]');
      if (label) label.textContent = index > 0 ? t('visualizationRowGroupNextBy') : t('visualizationRowGroupBy');
    });
  }

  function applyObjectPathFilter(container) {
    Array.prototype.slice.call((container || document).querySelectorAll('[data-object-selection]')).forEach(function (selection) {
      var filter = selection.querySelector('[data-object-path-filter]');
      if (!filter) return;
      var domain = String((filter.querySelector('[data-object-path-filter-field="domain"]') || {}).value || '').trim().toLowerCase();
      var cardinality = String((filter.querySelector('[data-object-path-filter-field="cardinality"]') || {}).value || '').trim().toLowerCase();
      var direction = String((filter.querySelector('[data-object-path-filter-field="direction"]') || {}).value || '').trim().toLowerCase();
      Array.prototype.slice.call(selection.querySelectorAll('[data-object-scope-field="path"] option')).forEach(function (option) {
        if (!option.value) {
          option.hidden = false;
          return;
        }
        var matches = true;
        if (domain && String(option.getAttribute('data-domain') || '').toLowerCase() !== domain) matches = false;
        if (cardinality && String(option.getAttribute('data-cardinality') || '').toLowerCase() !== cardinality) matches = false;
        if (direction && String(option.getAttribute('data-direction') || '').toLowerCase() !== direction) matches = false;
        option.hidden = !matches;
      });
    });
  }

  function visualizationColumnOptionsHtmlForRowGroup(container) {
    var detailRow = container && container.closest ? container.closest('[data-visualization-row-detail]') : null;
    var source = detailRow && detailRow.querySelector('[data-visualization-column-options]');
    if (source && source.innerHTML) return source.innerHTML;
    source = detailRow && detailRow.querySelector('[data-visualization-field="groupBy"]');
    if (source && source.innerHTML) return source.innerHTML;
    source = detailRow && detailRow.querySelector('[data-visualization-field="sortColumn"]');
    if (source && source.innerHTML) return source.innerHTML;
    source = container && container.querySelector('[data-visualization-field="rowGroupBy"]');
    return source && source.innerHTML ? source.innerHTML : '<option value=""></option>';
  }

  function addVisualizationRowGroup(button) {
    var container = button && button.closest ? button.closest('[data-visualization-row-groups]') : null;
    if (!container) return;
    var options = visualizationColumnOptionsHtmlForRowGroup(container);
    var insertBefore = container.querySelector('[data-visualization-row-group-insert]') || button.parentElement || container;
    insertBefore.insertAdjacentHTML('beforebegin',
      '<div class="visual-row-group" data-visualization-row-group>' +
      '<label><span data-row-group-label>' + t('visualizationRowGroupNextBy') + '</span><select data-visualization-field="rowGroupBy">' + options + '</select></label>' +
      '<button data-action="clear-visual-row-group" type="button">' + t('clear') + '</button>' +
      '</div>');
    refreshVisualizationRowGroupLabels(container);
  }

  function clearVisualizationRowGroup(button) {
    var row = button && button.closest ? button.closest('[data-visualization-row-group]') : null;
    var container = button && button.closest ? button.closest('[data-visualization-row-groups]') : null;
    if (!row || !container) return;
    var rows = Array.prototype.slice.call(container.querySelectorAll('[data-visualization-row-group]'));
    if (rows.length <= 1) {
      var select = row.querySelector('[data-visualization-field="rowGroupBy"]');
      if (select) select.value = '';
      return;
    }
    row.remove();
    refreshVisualizationRowGroupLabels(container);
  }

  function saveTemplate() {
    if (state.diagramImportProposal) {
      state.message = { type: 'error', text: t(state.diagramImportStale ? 'diagramImportStale' : 'diagramImportReviewBlocked') };
      renderDesigner();
      return;
    }
    if (state.diagramImportStale) {
      state.message = { type: 'error', text: t('diagramImportStale') };
      renderDesigner();
      return;
    }
    if (state.diagramImportAppliedPendingPreview && !state.lastDraftPreviewOk) {
      state.message = { type: 'error', text: t('diagramImportPreviewRequired') };
      renderDesigner();
      return;
    }
    var payload;
    try { payload = readEditorPayload(); } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    var exists = Boolean(state.selectedTemplate && state.selectedTemplate.id);
    var path = exists ? apiPrefix + '/templates/' + encodeURIComponent(state.selectedTemplate.code) : apiPrefix + '/templates';
    var wasCreating = state.designerSection === 'template';
    request(path, { method: exists ? 'PUT' : 'POST', body: payload }).then(function (result) {
      if (!result.ok) throw new Error(errorText(result));
      state.selectedTemplate = result.json.template;
      var saveMessage = result.json.cacheInvalidation && result.json.cacheInvalidation.complete === false
        ? { type: 'error', text: t('diagramImportCacheInvalidationPartial') }
        : { type: 'ok', text: t('saved') };
      state.message = saveMessage;
      state.paramRowsDraft = null;
      state.lastDraftPreviewOk = false;
      state.diagramImportAppliedPendingPreview = false;
      if (wasCreating) {
        state.designerSection = 'templates';
        if (window.history && window.history.pushState) window.history.pushState({ designerSection: 'templates' }, '', designerSectionUrl('templates'));
      }
      return loadDesigner({ preserveAssistantState: true }).then(function () {
        state.message = saveMessage;
        renderDesigner();
      });
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
    });
  }

  function openAssistantSection() {
    setDesignerSection('assistant');
  }

  function assistantCompletionText(json, fallback) {
    var parts = [String(json && json.explanation || fallback || '').trim()].filter(Boolean);
    var warnings = json && Array.isArray(json.warnings) ? json.warnings.map(function (item) { return String(item || '').trim(); }).filter(Boolean) : [];
    if (warnings.length) parts.push(t('assistantWarnings') + ': ' + warnings.join(' '));
    return parts.join(' ');
  }

  function captureAssistantObjectFlow() {
    captureAssistantPromptsFromDom();
    if (!state.assistantFlowProposal) throw new Error(t('assistantNoFlowProposal'));
    return cloneJsonValue(state.assistantFlowProposal, { version: 1, selections: [], blocks: [] });
  }

  function assistantSpecWithPrompts(spec) {
    var next = cloneSpecForEdit(spec || defaultSpec());
    next.assistantDraft = Object.assign({}, next.assistantDraft || {}, assistantPromptDraft());
    delete next.assistantDraft.objectFlowPrompt;
    delete next.assistantDraft.flowPrompts;
    delete next.assistantDraft.intent;
    delete next.assistantDraft.taskMode;
    return next;
  }

  function updateAssistantObjectFlowIntent(mutator) {
    if (state.assistantFlowBusy) return;
    captureAssistantPromptsFromDom();
    var next = normalizeAssistantObjectFlowIntentClient(state.assistantObjectFlowIntent);
    mutator(next);
    state.assistantObjectFlowIntent = next;
    resetAssistantObjectFlowProposal();
    scheduleAssistantPromptAutosave();
    renderDesigner();
  }

  function addAssistantObjectFlowBlock() {
    updateAssistantObjectFlowIntent(function (intent) {
      var block = defaultAssistantObjectFlowBlock(intent.blocks.length, intent.blocks.map(function (item) { return item.id; }));
      state.assistantFlowExpandedBlockIds[block.id] = true;
      intent.blocks.push(block);
    });
  }

  function removeAssistantObjectFlowBlock(index) {
    updateAssistantObjectFlowIntent(function (intent) {
      var removed = intent.blocks.splice(Number(index), 1)[0];
      if (!removed) return;
      delete state.assistantFlowExpandedBlockIds[removed.id];
      if (intent.extractionCandidateBlockId === removed.id) {
        intent.extractionCandidateBlockId = '';
        intent.extractionCandidateAlias = '';
      }
      intent.blocks.forEach(function (block) {
        block.uses = block.uses.filter(function (dependency) { return dependency !== removed.id; });
      });
    });
  }

  function moveAssistantObjectFlowBlockTo(from, to) {
    updateAssistantObjectFlowIntent(function (intent) {
      if (from < 0 || to < 0 || from >= intent.blocks.length || to >= intent.blocks.length) return;
      var block = intent.blocks.splice(from, 1)[0];
      intent.blocks.splice(to, 0, block);
    });
  }

  function newAssistantSemanticPlanResumeId() {
    if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID();
    return 'semantic-' + String(Date.now()) + '-' + Math.random().toString(36).slice(2, 18);
  }

  function assistantSemanticPlanResumeMatches(resume, intent, spec) {
    return Boolean(resume && resume.resumeId
      && resume.intentFingerprint === stableClientJsonStringify(intent)
      && resume.specFingerprint === stableClientJsonStringify(assistantSpecWithoutPromptDraft(spec)));
  }

  function setAssistantSemanticPlanRetryState(resume, diagnostics, checkpointConfirmed) {
    state.assistantFlowResume = Object.assign({}, resume || {}, { retryable: true, retryStage: 'semanticPlan', checkpointConfirmed: Boolean(checkpointConfirmed) });
    state.assistantFlowRejected = null;
    state.assistantFlowErrors = [];
    state.assistantFlowDiagnostics = diagnostics && typeof diagnostics === 'object' ? diagnostics : {};
    state.assistantFlowFeedback = {
      summary: t('assistantSemanticPlanPaused'),
      action: checkpointConfirmed ? t('assistantSemanticPlanRetryReady') : t('assistantSemanticPlanRetryUnknown')
    };
    state.assistantFlowErrorStage = 'semanticPlan';
    state.message = { type: 'error', text: state.assistantFlowFeedback.action };
  }

  function setAssistantObjectFlowPlanRetryState(resume, diagnostics, transport) {
    state.assistantFlowResume = Object.assign({}, resume || {}, { retryable: true, retryStage: 'flowDraft', checkpointConfirmed: true });
    state.assistantFlowRejected = null;
    state.assistantFlowErrors = [];
    state.assistantFlowDiagnostics = diagnostics && typeof diagnostics === 'object' ? diagnostics : {};
    state.assistantFlowFeedback = {
      summary: t('assistantFlowPlanPaused'),
      action: transport === 'gateway' ? t('assistantFlowPlanRetryGateway') : t('assistantFlowPlanRetryReady')
    };
    state.assistantFlowErrorStage = 'flowDraft';
    state.message = { type: 'error', text: state.assistantFlowFeedback.action };
  }

  function prepareAssistantObjectFlowSemanticPlan(retry) {
    if (state.assistantFlowBusy) return;
    captureAssistantPromptsFromDom();
    var requestSpec = state.selectedTemplate && state.selectedTemplate.spec || defaultSpec();
    var intent = cloneJsonValue(state.assistantObjectFlowIntent, { context: '', blocks: [] });
    var duplicateName = assistantObjectFlowDuplicateNameError(intent.blocks);
    if (duplicateName) {
      state.assistantFlowFeedback = { summary: t('assistantFlowDuplicateBlockName'), action: t('assistantFlowDuplicateBlockNameAction') };
      state.assistantFlowErrors = [{ path: '$.assistantDraft.objectFlowIntent.blocks', message: t('assistantFlowDuplicateBlockName', { name: duplicateName }) }];
      state.assistantFlowErrorStage = 'semanticPlan';
      state.message = { type: 'error', text: t('assistantFlowDuplicateBlockName', { name: duplicateName }) };
      renderDesigner();
      return;
    }
    var previousResume = retry && assistantSemanticPlanResumeMatches(state.assistantFlowResume, intent, requestSpec) ? state.assistantFlowResume : null;
    var resume = previousResume || {
      resumeId: newAssistantSemanticPlanResumeId(),
      intentFingerprint: stableClientJsonStringify(intent),
      specFingerprint: stableClientJsonStringify(assistantSpecWithoutPromptDraft(requestSpec)),
      checkpointConfirmed: false
    };
    var requestGeneration = Number(state.assistantFlowRequestGeneration || 0) + 1;
    state.assistantFlowRequestGeneration = requestGeneration;
    var requestRevision = assistantTemplateRevisionSnapshot(state.selectedTemplate, requestSpec, requestGeneration);
    state.assistantFlowBusy = true;
    state.assistantFlowResume = resume;
    resetAssistantObjectFlowProposal({ preserveResume: true });
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();

    function requestSemanticPlanStage(stage) {
      return request(apiPrefix + '/assistant/object-flow/semantic-plan?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), {
        method: 'POST', timeoutMs: assistantRequestTimeoutMs(1),
        body: {
          stage: stage,
          resumeId: resume.resumeId,
          intent: intent,
          currentSpec: requestSpec,
          templateCode: state.selectedTemplate && state.selectedTemplate.code || '',
          baseSpecHash: state.selectedTemplate && state.selectedTemplate.specHash || ''
        }
      }).then(function (result) {
        var mismatch = assistantTemplateRevisionMismatch(requestRevision);
        if (mismatch === 'request') throw assistantTemplateRevisionError(requestRevision);
        if (result.ok && result.json && result.json.checkpoint && !result.json.semanticPlan) {
          resume = Object.assign({}, resume, result.json.checkpoint || {}, { checkpointConfirmed: true });
          state.assistantFlowResume = resume;
          return requestSemanticPlanStage('plan');
        }
        if (!result.ok && result.json && result.json.retryable) {
          resume = Object.assign({}, resume, result.json.resume || {}, { checkpointConfirmed: Boolean(result.json.resume) });
          setAssistantSemanticPlanRetryState(resume, result.json.diagnostics, Boolean(result.json.resume));
          return;
        }
        if (!result.ok && result.json && result.json.code === 'assistant_semantic_plan_invalid') {
          state.assistantFlowResume = null;
          state.assistantFlowRejected = null;
          state.assistantFlowErrors = Array.isArray(result.json.errors) ? result.json.errors : [];
          state.assistantFlowDiagnostics = result.json.diagnostics && typeof result.json.diagnostics === 'object' ? result.json.diagnostics : {};
          state.assistantFlowFeedback = result.json.feedback && typeof result.json.feedback === 'object' ? result.json.feedback : null;
          state.assistantFlowErrorStage = 'semanticPlan';
          state.message = { type: 'error', text: state.assistantFlowFeedback && state.assistantFlowFeedback.summary || errorText(result) };
          return;
        }
        if (!result.ok || !result.json || !result.json.semanticPlan) throw new Error(errorText(result));
        var staleError = assistantTemplateRevisionError(requestRevision);
        if (staleError) throw staleError;
        resume = Object.assign({}, resume, result.json.resume || {}, { checkpointConfirmed: true, retryable: false, retryStage: '' });
        state.assistantFlowResume = resume;
        state.assistantFlowSemanticPlan = cloneJsonValue(result.json.semanticPlan, { version: 1, blocks: [] });
        state.assistantFlowExplanation = String(result.json.explanation || '');
        state.assistantFlowWarnings = Array.isArray(result.json.warnings) ? result.json.warnings.map(String).filter(Boolean) : [];
        state.message = { type: 'ok', text: assistantCompletionText(result.json, t('assistantFlowReady')) };
      });
    }

    requestSemanticPlanStage(previousResume ? 'plan' : 'context').catch(function (error) {
      if (!assistantTemplateRevisionMismatch(requestRevision)) {
        setAssistantSemanticPlanRetryState(resume, {}, Boolean(resume && resume.checkpointConfirmed));
        return;
      }
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      if (Number(state.assistantFlowRequestGeneration || 0) === requestGeneration) state.assistantFlowBusy = false;
      renderDesigner();
    });
  }

  function generateAssistantObjectFlow(retry) {
    if (state.assistantFlowBusy || !state.assistantFlowSemanticPlan) return;
    captureAssistantPromptsFromDom();
    var requestSpec = state.selectedTemplate && state.selectedTemplate.spec || defaultSpec();
    var resume = assistantSemanticPlanResumeMatches(state.assistantFlowResume, state.assistantObjectFlowIntent, requestSpec) && state.assistantFlowResume.checkpointConfirmed
      ? state.assistantFlowResume
      : null;
    if (!resume) {
      state.assistantFlowFeedback = {
        summary: t('assistantFlowPlanPaused'),
        action: t('assistantSemanticPlanRetryUnknown')
      };
      state.assistantFlowErrorStage = 'flowDraft';
      state.message = { type: 'error', text: state.assistantFlowFeedback.action };
      renderDesigner();
      return;
    }
    var requestGeneration = Number(state.assistantFlowRequestGeneration || 0) + 1;
    state.assistantFlowRequestGeneration = requestGeneration;
    var requestRevision = assistantTemplateRevisionSnapshot(state.selectedTemplate, requestSpec, requestGeneration);
    state.assistantFlowBusy = true;
    state.assistantFlowProposal = null;
    state.assistantFlowRejected = null;
    state.assistantFlowErrors = [];
    state.assistantFlowDiagnostics = {};
    state.assistantFlowFeedback = null;
    state.assistantFlowErrorStage = '';
    state.assistantFlowPreview = null;
    state.assistantFlowCanApply = false;
    state.assistantFlowCandidateOutput = null;
    state.assistantFlowOutputBindings = [];
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();
    request(apiPrefix + '/assistant/object-flow/plan?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), {
      method: 'POST', timeoutMs: assistantRequestTimeoutMs(1),
      body: {
        resumeId: resume.resumeId,
        intent: state.assistantObjectFlowIntent,
        semanticPlan: state.assistantFlowSemanticPlan,
        currentSpec: requestSpec,
        templateCode: state.selectedTemplate && state.selectedTemplate.code || '',
        baseSpecHash: state.selectedTemplate && state.selectedTemplate.specHash || ''
      }
    }).then(function (result) {
      var mismatch = assistantTemplateRevisionMismatch(requestRevision);
      if (mismatch === 'request') throw assistantTemplateRevisionError(requestRevision);
      if (!result.ok && result.json && result.json.retryable) {
        setAssistantObjectFlowPlanRetryState(Object.assign({}, resume, result.json.resume || {}), result.json.diagnostics, 'backend');
        return;
      }
      if (!result.ok && result.status === 504) {
        setAssistantObjectFlowPlanRetryState(resume, {}, 'gateway');
        return;
      }
      if (!result.ok && result.json && result.json.code === 'assistant_object_flow_invalid') {
        state.assistantFlowRejected = result.json.rejectedFlow && typeof result.json.rejectedFlow === 'object' ? cloneJsonValue(result.json.rejectedFlow, { version: 1, selections: [], operations: [] }) : null;
        state.assistantFlowErrors = Array.isArray(result.json.errors) ? result.json.errors : [];
        state.assistantFlowDiagnostics = result.json.diagnostics && result.json.diagnostics.objectFlow || {};
        state.assistantFlowFeedback = result.json.feedback && typeof result.json.feedback === 'object' ? result.json.feedback : null;
        state.assistantFlowWarnings = Array.isArray(result.json.warnings) ? result.json.warnings.map(String).filter(Boolean) : [];
        state.message = { type: 'error', text: state.assistantFlowFeedback && state.assistantFlowFeedback.summary || t('assistantFlowRejected') };
        return;
      }
      if (!result.ok || !result.json || !result.json.flow) throw new Error(errorText(result));
      var staleError = assistantTemplateRevisionError(requestRevision);
      if (staleError) throw staleError;
      state.assistantFlowProposal = cloneJsonValue(result.json.flow, { version: 1, selections: [], blocks: [] });
      state.assistantFlowCanApply = result.json.canApply === true;
      state.assistantFlowExplanation = String(result.json.explanation || '');
      state.assistantFlowWarnings = Array.isArray(result.json.warnings) ? result.json.warnings.map(String).filter(Boolean) : [];
      state.assistantFlowCandidateOutput = result.json.extractionCandidate && typeof result.json.extractionCandidate === 'object'
        ? { blockId: String(result.json.extractionCandidate.blockId || ''), alias: String(result.json.extractionCandidate.alias || '') }
        : null;
      state.assistantFlowOutputBindings = Array.isArray(result.json.outputBindings)
        ? result.json.outputBindings.map(function (binding) {
          return { blockId: String(binding && binding.blockId || ''), alias: String(binding && binding.alias || '') };
        }).filter(function (binding) { return binding.blockId && binding.alias; })
        : [];
      state.assistantFlowErrors = Array.isArray(result.json.ownershipErrors) ? result.json.ownershipErrors : [];
      state.assistantFlowFeedback = state.assistantFlowErrors.length
        ? { summary: t('assistantFlowOwnershipIncomplete'), action: t('assistantFlowOwnershipIncompleteAction') }
        : null;
      state.assistantFlowErrorStage = state.assistantFlowErrors.length ? 'ownership' : '';
      state.assistantFlowResume = Object.assign({}, resume, { retryable: false, retryStage: '' });
      state.message = state.assistantFlowErrors.length
        ? { type: 'error', text: t('assistantFlowOwnershipIncomplete') }
        : { type: 'ok', text: assistantCompletionText(result.json, t('assistantFlowReady')) };
    }).catch(function (error) {
      if (resume && /^Request timeout:/.test(String(error && error.message || ''))) {
        setAssistantObjectFlowPlanRetryState(resume, {}, 'gateway');
        return;
      }
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      if (Number(state.assistantFlowRequestGeneration || 0) === requestGeneration) state.assistantFlowBusy = false;
      renderDesigner();
    });
  }

  function previewAssistantObjectFlow() {
    if (state.assistantFlowBusy || !state.assistantFlowProposal) return;
    var requestSpec = state.selectedTemplate && state.selectedTemplate.spec || defaultSpec();
    var params;
    try {
      params = readRunParams();
    } catch (error) {
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
      return;
    }
    var requestGeneration = Number(state.assistantFlowRequestGeneration || 0) + 1;
    state.assistantFlowRequestGeneration = requestGeneration;
    var requestRevision = assistantTemplateRevisionSnapshot(state.selectedTemplate, requestSpec, requestGeneration);
    state.assistantFlowBusy = true;
    state.assistantFlowPreview = null;
    state.runParams = Object.assign({}, state.runParams || {}, params);
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();
    request(apiPrefix + '/assistant/object-flow/preview?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), {
      method: 'POST', timeoutMs: 60000,
      body: {
        flow: state.assistantFlowProposal,
        assistantOutputBindings: state.assistantFlowOutputBindings,
        assistantObjectFlowIntent: state.assistantObjectFlowIntent,
        currentSpec: requestSpec,
        params: params,
        templateCode: state.selectedTemplate && state.selectedTemplate.code || '',
        baseSpecHash: state.selectedTemplate && state.selectedTemplate.specHash || ''
      }
    }).then(function (result) {
      var mismatch = assistantTemplateRevisionMismatch(requestRevision);
      if (mismatch === 'request') throw assistantTemplateRevisionError(requestRevision);
      if (!result.ok) {
        state.assistantFlowPreview = result;
        state.message = { type: 'error', text: errorText(result) };
        return;
      }
      var staleError = assistantTemplateRevisionError(requestRevision);
      if (staleError) throw staleError;
      state.assistantFlowPreview = result;
      state.message = { type: 'ok', text: t('assistantFlowPreviewReady') };
    }).catch(function (error) {
      state.assistantFlowPreview = null;
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      if (Number(state.assistantFlowRequestGeneration || 0) === requestGeneration) state.assistantFlowBusy = false;
      renderDesigner();
    });
  }

  function applyAssistantObjectFlow() {
    if (state.assistantFlowBusy || !state.assistantFlowCanApply) {
      state.message = { type: 'error', text: t('assistantFlowApplyUnavailable') };
      renderDesigner();
      return;
    }
    var flow;
    try { flow = captureAssistantObjectFlow(); } catch (error) {
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
      return;
    }
    var requestSpec = state.selectedTemplate && state.selectedTemplate.spec || defaultSpec();
    var requestGeneration = Number(state.assistantFlowRequestGeneration || 0) + 1;
    state.assistantFlowRequestGeneration = requestGeneration;
    var requestRevision = assistantTemplateRevisionSnapshot(
      state.selectedTemplate,
      requestSpec,
      requestGeneration
    );
    var requestFlowFingerprint = stableClientJsonStringify(flow);
    var requestIntentFingerprint = stableClientJsonStringify(state.assistantObjectFlowIntent);
    var requestOutputBindingsFingerprint = stableClientJsonStringify(state.assistantFlowOutputBindings);
    state.assistantFlowBusy = true;
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();
    request(apiPrefix + '/draft/object-flow/apply', {
      method: 'POST', timeoutMs: 30000,
      body: {
        root: state.root,
        currentSpec: requestSpec,
        flow: flow,
        assistantOutputBindings: state.assistantFlowOutputBindings,
        assistantObjectFlowIntent: state.assistantObjectFlowIntent,
        templateCode: state.selectedTemplate && state.selectedTemplate.code || '',
        baseSpecHash: state.selectedTemplate && state.selectedTemplate.specHash || ''
      }
    }).then(function (result) {
      var mismatch = assistantTemplateRevisionMismatch(requestRevision);
      if (mismatch === 'request') throw assistantTemplateRevisionError(requestRevision);
      if (stableClientJsonStringify(state.assistantFlowProposal) !== requestFlowFingerprint
        || stableClientJsonStringify(state.assistantObjectFlowIntent) !== requestIntentFingerprint
        || stableClientJsonStringify(state.assistantFlowOutputBindings) !== requestOutputBindingsFingerprint) {
        throw assistantTemplateRevisionError(Object.assign({}, requestRevision, { requestGeneration: -1 }));
      }
      if (!result.ok || !result.json || !result.json.spec) throw new Error(errorText(result));
      var staleError = assistantTemplateRevisionError(requestRevision);
      if (staleError) throw staleError;
      var candidateOutput = state.assistantFlowCandidateOutput;
      if (candidateOutput && candidateOutput.blockId === state.assistantObjectFlowIntent.extractionCandidateBlockId && candidateOutput.alias) {
        state.assistantObjectFlowIntent.extractionCandidateAlias = candidateOutput.alias;
      } else {
        state.assistantObjectFlowIntent.extractionCandidateAlias = '';
      }
      updateSelectedFromEditor(assistantSpecWithPrompts(result.json.spec));
      state.objectGroupDraft = null;
      state.relationDraft = null;
      state.assistantFlowProposal = null;
      state.assistantFlowRefinement = null;
      state.assistantFlowRejected = null;
      state.assistantFlowErrors = [];
      state.assistantFlowDiagnostics = {};
      state.assistantFlowFeedback = null;
      state.assistantFlowErrorStage = '';
      state.assistantFlowPreview = null;
      state.assistantFlowCanApply = false;
      state.assistantFlowExplanation = '';
      state.assistantFlowWarnings = [];
      state.assistantFlowCandidateOutput = null;
      state.assistantFlowOutputBindings = [];
      if (state.diagramImportProposal) state.diagramImportStale = true;
      clearDraftExecutionState({ clearExtractionSource: true });
      state.message = { type: 'ok', text: t('assistantFlowApplied') };
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      if (Number(state.assistantFlowRequestGeneration || 0) === requestGeneration) state.assistantFlowBusy = false;
      renderDesigner();
    });
  }

  function assistantDiagramRequest(kind) {
    if (state.assistantDiagramInterpretBusy || state.assistantDiagramMappingBusy || !state.diagramImportSignedProposal) return;
    if (!captureVisibleDesignerState()) return;
    var proposal = state.diagramImportProposal;
    var prompt = kind === 'interpret' ? state.assistantDiagramInterpretPrompt.trim() : state.assistantDiagramMappingPrompt.trim();
    if (!prompt) {
      state.message = { type: 'error', text: t('fieldRequired', { label: kind === 'interpret' ? t('assistantDiagramInterpretPrompt') : t('assistantDiagramMappingPrompt') }) };
      renderDesigner();
      return;
    }
    if (kind === 'interpret') state.assistantDiagramInterpretBusy = true;
    else state.assistantDiagramMappingBusy = true;
    var requestTemplate = state.selectedTemplate;
    var requestProposal = state.diagramImportProposal;
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();
    var body = {
      prompt: prompt,
      currentSpec: state.selectedTemplate && state.selectedTemplate.spec || defaultSpec(),
      proposal: state.diagramImportSignedProposal,
      roles: diagramImportBindingOverrides(proposal),
      relationRules: cloneJsonValue(proposal.relationRules || [], []),
      placementRules: cloneJsonValue(proposal.placementRules || [], [])
    };
    if (kind === 'map') body.stages = assistantFlowStageSummaries(assistantFlowModel(body.currentSpec), body.currentSpec);
    request(apiPrefix + '/assistant/diagram-import/' + (kind === 'interpret' ? 'interpret' : 'map-selections') + '?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), { method: 'POST', timeoutMs: assistantRequestTimeoutMs(), body: body }).then(function (result) {
      if (state.selectedTemplate !== requestTemplate || state.diagramImportProposal !== requestProposal) throw new Error(t('assistantResponseStale'));
      if (!result.ok || !result.json) throw new Error(errorText(result));
      if (kind === 'interpret') {
        state.assistantDiagramInterpretResult = result.json;
        (result.json.decisions || []).forEach(function (decision) {
          var role = (proposal.roles || []).find(function (item) { return item.id === decision.roleId; });
          if (role && decision.semantic) role.selectedSemantic = decision.semantic;
          if (role && decision.reason) role.semanticReason = decision.reason;
        });
      } else {
        state.assistantDiagramMappingResult = result.json;
        (result.json.mappings || []).forEach(function (candidate) {
          var role = (proposal.roles || []).find(function (item) { return item.id === candidate.roleId; });
          if (!role) return;
          role.mapping = Object.assign({}, role.mapping || {}, candidate.mapping || {}, { source: candidate.source || candidate.mapping && candidate.mapping.source || {} });
        });
      }
      refreshDiagramImportSemanticState(proposal);
      state.diagramImportProposal = proposal;
      state.message = { type: 'ok', text: assistantCompletionText(result.json, t('assistantDraftGenerated')) };
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
    }).finally(function () {
      state.assistantDiagramInterpretBusy = false;
      state.assistantDiagramMappingBusy = false;
      renderDesigner();
    });
  }

  function assistantFlowModel(spec) {
    return inferRelationExpansionModel(spec || defaultSpec());
  }

  function assistantFlowStageSummaries(model, spec) {
    var summaries = [];
    var columnsByAlias = {};
    (model.selections || []).forEach(function (selection, index) {
      var columns = uniqueList(['Class', '_id', 'Code', 'Description'].concat(selection.columns || []));
      summaries.push({ id: selection.id, kind: 'selection', index: index, label: selection.name || defaultObjectSelectionName(index), alias: selection.alias, className: selection.className, columns: columns });
      columnsByAlias[selection.alias] = columns;
    });
    var matchIndex = 0;
    var setIndex = 0;
    flowOperations(model).forEach(function (operation) {
      var leftColumns = columnsByAlias[operation.from] || [];
      var rightColumns = columnsByAlias[operation.with] || [];
      var columns;
      if (operation.type === 'match') {
        columns = leftColumns.slice();
        var prefix = operation.rightPrefix || objectSelectionOutputPrefix(spec || defaultSpec(), operation.with);
        rightColumns.forEach(function (column) {
          if (columns.indexOf(prefix + column) === -1) columns.push(prefix + column);
        });
        (operation.rules || []).forEach(function (rule) {
          if (rule.leftColumn && columns.indexOf(rule.leftColumn) === -1) columns.push(rule.leftColumn);
          if (rule.rightColumn && columns.indexOf(prefix + rule.rightColumn) === -1) columns.push(prefix + rule.rightColumn);
        });
        summaries.push({ id: operation.id, kind: 'match', index: matchIndex, label: t('matchingBlock', { number: matchIndex + 1 }), alias: operation.as, columns: columns });
        matchIndex += 1;
      } else if (operation.type === 'relation') {
        columns = uniqueList(['SourceClass', 'SourceId', 'SourceCode', 'SourceDescription', 'Domain', 'RelationId', 'RelationDirection', 'RelationSourceSide', 'RelatedClass', 'RelatedId', 'Class', '_id', 'Code', 'Description'].concat(operation.columns || []));
        summaries.push({ id: operation.id, kind: 'relation', index: index, label: t('relationOperation', { number: index + 1 }), alias: operation.as, className: operation.targetClass || '', columns: columns });
      } else if (operation.type === 'existsRelated') {
        columns = leftColumns.slice();
        summaries.push({ id: operation.id, kind: 'existsRelated', index: index, label: t('existsRelatedOperation', { number: index + 1 }), alias: operation.as, className: sourceClassForAlias(spec || defaultSpec(), operation.as), columns: columns });
      } else {
        columns = operation.type === 'union' ? uniqueList(leftColumns.concat(rightColumns)) : leftColumns.slice();
        summaries.push({ id: operation.id, kind: 'set', index: setIndex, label: t('setOperation', { number: setIndex + 1 }), alias: operation.as, className: sourceClassForAlias(spec || defaultSpec(), operation.as), columns: columns });
        setIndex += 1;
      }
      columnsByAlias[operation.as] = columns;
    });
    return summaries;
  }

  function refreshAssistantGenerationElapsed() {
    var node = document.querySelector('[data-assistant-elapsed]');
    if (node) node.textContent = assistantGenerationElapsedText();
  }

  function stopAssistantGenerationTimer() {
    if (state.assistantGenerationTimer) {
      window.clearInterval(state.assistantGenerationTimer);
      state.assistantGenerationTimer = null;
    }
  }

  function startAssistantGenerationTimer() {
    stopAssistantGenerationTimer();
    refreshAssistantGenerationElapsed();
    state.assistantGenerationTimer = window.setInterval(refreshAssistantGenerationElapsed, 1000);
  }

  function generateAssistantDraft() {
    if (state.assistantGenerating) return;
    if (!captureVisibleDesignerState()) return;
    var intent = String(state.assistantDraftIntent || '').trim();
    if (!intent) {
      state.message = { type: 'error', text: t('fieldRequired', { label: t('assistantIntent') }) };
      renderDesigner();
      return;
    }
    var currentSpec = state.selectedTemplate && state.selectedTemplate.spec ? state.selectedTemplate.spec : defaultSpec();
    state.assistantGenerating = true;
    state.assistantGeneratingStartedAt = Date.now();
    state.message = { type: 'ok', text: t('assistantGeneratingTitle') };
    renderDesigner();
    startAssistantGenerationTimer();
    request(apiPrefix + '/assistant/template-draft?root=' + encodeURIComponent(state.root || 'Cst_QueryTool'), {
      method: 'POST',
      timeoutMs: assistantRequestTimeoutMs(),
      body: {
        intent: intent,
        taskMode: state.assistantTaskMode,
        currentSpec: currentSpec
      }
    }).then(function (result) {
      state.assistantDraftResult = result;
      if (result.ok && result.json && result.json.spec) {
        state.objectGroupDraft = null;
        state.relationDraft = null;
        state.viewComposerDraft = null;
        updateSelectedFromEditor(applyAssistantDraftToSpec(result.json.spec, state.assistantDraftIntent, state.assistantTaskMode));
        clearDraftExecutionState();
        state.message = { type: 'ok', text: t('assistantDraftGeneratedApplied') };
      } else {
        state.message = { type: result.ok ? 'ok' : 'error', text: result.ok ? t('assistantDraftGenerated') : errorText(result) };
      }
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message };
    }).finally(function () {
      state.assistantGenerating = false;
      state.assistantGeneratingStartedAt = 0;
      stopAssistantGenerationTimer();
      renderDesigner();
    });
  }

  function applyAssistantDraft() {
    if (!captureVisibleDesignerState()) return;
    var result = state.assistantDraftResult;
    if (!result || !result.ok || !result.json || !result.json.spec) {
      state.message = { type: 'error', text: t('assistantNoDraft') };
      renderDesigner();
      return;
    }
    state.objectGroupDraft = null;
    state.relationDraft = null;
    state.viewComposerDraft = null;
    updateSelectedFromEditor(applyAssistantDraftToSpec(result.json.spec, state.assistantDraftIntent, state.assistantTaskMode));
    state.message = {
      type: 'ok',
      text: result.json.explanation ? t('assistantDraftApplied') + ' ' + result.json.explanation : t('assistantDraftApplied')
    };
    clearDraftExecutionState();
    renderDesigner();
  }

  function runDraftAction(action) {
    var code = readTemplateCode();
    if (!code) {
      state.message = { type: 'error', text: t('templateCodeRequired') };
      renderDesigner();
      return;
    }
    var payload;
    var params;
    try {
      payload = readEditorPayload();
      params = readRunParams();
    } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    request(apiPrefix + '/draft/' + action + '?maxRows=25', {
      method: 'POST',
      body: { template: payload, params: params }
    }).then(function (result) {
      result.downloadMode = 'draft';
      state.result = result;
      state.lastDraftPreviewOk = action === 'preview' && result.ok;
      if (state.lastDraftPreviewOk) state.diagramImportAppliedPendingPreview = false;
      state.message = { type: result.ok ? 'ok' : 'error', text: result.ok ? t(action === 'validate' ? 'draftValidateCompleted' : 'draftPreviewCompleted') : errorText(result) };
      state.designerSection = 'run';
      if (window.history && window.history.pushState) window.history.pushState({ designerSection: 'run' }, '', designerSectionUrl('run'));
      renderDesigner();
    }).catch(function (error) {
      state.lastDraftPreviewOk = false;
      state.message = { type: 'error', text: error.message };
      renderDesigner();
    });
  }

  function saveAfterTest() {
    if (!state.lastDraftPreviewOk) {
      state.message = { type: 'error', text: t('saveNeedsPreview') };
      renderDesigner();
      return;
    }
    saveTemplate();
  }

  function bootstrapSchema() {
    var root = readValue('cmdp-root') || state.root;
    var description = readValue('cmdp-schema-description') || currentSchemaDescription();
    var parent = readValue('cmdp-schema-parent') || currentSchemaParent();
    var classes = schemaClassOverridesPayload(state.schemaPlan || state.schema);
    var rootOverride = classes.find(function (item) { return item.role === 'root'; });
    if (rootOverride && rootOverride.name) root = rootOverride.name;
    state.root = root;
    state.schemaRootDraft = root;
    state.schemaDescriptionDraft = description;
    state.schemaParentDraft = parent;
    state.schemaClassDrafts = readSchemaClassDraftsFromDom();
    if (hasField('cmdp-schema-confirm') && !readChecked('cmdp-schema-confirm')) {
      state.message = { type: 'error', text: t('schemaConfirmRequired') };
      renderDesigner();
      return;
    }
    if (!canBootstrapSchema()) {
      state.message = { type: 'error', text: t('bootstrapRequiresAdmin') };
      renderDesigner();
      return;
    }
    request(apiPrefix + '/schema/bootstrap', { method: 'POST', body: { root: root, description: description, parent: parent, classes: classes, confirm: true } }).then(function (result) {
      state.schema = result.json ? result.json.schema : null;
      state.schemaPlan = state.schema;
      state.schemaClassDrafts = schemaClassDraftsFromPlan(state.schemaPlan);
      state.message = { type: result.ok ? 'ok' : 'error', text: result.ok ? t('schemaBootstrapDone') : errorText(result) };
      renderDesigner();
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
    });
  }

  function previewSchema() {
    var root = readValue('cmdp-root') || state.root;
    var description = readValue('cmdp-schema-description') || currentSchemaDescription();
    var parent = readValue('cmdp-schema-parent') || currentSchemaParent();
    var classes = schemaClassOverridesPayload(state.schemaPlan || state.schema);
    var rootOverride = classes.find(function (item) { return item.role === 'root'; });
    if (rootOverride && rootOverride.name) root = rootOverride.name;
    state.root = root;
    state.schemaRootDraft = root;
    state.schemaDescriptionDraft = description;
    state.schemaParentDraft = parent;
    state.schemaClassDrafts = readSchemaClassDraftsFromDom();
    request(apiPrefix + '/schema/preview', { method: 'POST', body: { root: root, description: description, parent: parent, classes: classes } }).then(function (result) {
      state.schemaPlan = result.json ? result.json.schema : null;
      state.schema = state.schemaPlan || state.schema;
      state.schemaClassDrafts = schemaClassDraftsFromPlan(state.schemaPlan);
      state.message = { type: result.ok ? 'ok' : 'error', text: result.ok ? t('schemaPreviewReady') : errorText(result) };
      renderDesigner();
    }).catch(function (error) {
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
    });
  }

  function applyRuntimeCacheFields(runtimeConfig) {
    var next = normalizeRuntimeConfigForEditor(runtimeConfig);
    if (hasField('cmdp-runtime-refresh-cooldown-sec')) {
      next.runtimeCache.refreshCooldownSec = readPositiveIntField('cmdp-runtime-refresh-cooldown-sec', t('runtimeRefreshCooldownSec'), next.runtimeCache.refreshCooldownSec);
    }
    return next;
  }

  function applyRuntimeExecutionLimitFields(runtimeConfig) {
    var next = normalizeRuntimeConfigForEditor(runtimeConfig);
    var fields = [
      ['cmdp-runtime-max-rows-default', 'runtimeMaxRowsDefault', 'maxRowsDefault'],
      ['cmdp-runtime-max-rows-preview-default', 'runtimeMaxRowsPreviewDefault', 'maxRowsPreviewDefault'],
      ['cmdp-runtime-max-rows-max', 'runtimeMaxRowsMax', 'maxRowsMax'],
      ['cmdp-runtime-max-classes-default', 'runtimeMaxClassesDefault', 'maxClassesDefault'],
      ['cmdp-runtime-max-classes-max', 'runtimeMaxClassesMax', 'maxClassesMax'],
      ['cmdp-runtime-max-domains-default', 'runtimeMaxDomainsDefault', 'maxDomainsDefault'],
      ['cmdp-runtime-max-domains-max', 'runtimeMaxDomainsMax', 'maxDomainsMax'],
      ['cmdp-runtime-max-rest-calls-default', 'runtimeMaxRestCallsDefault', 'maxRestCallsDefault'],
      ['cmdp-runtime-max-rest-calls-max', 'runtimeMaxRestCallsMax', 'maxRestCallsMax'],
      ['cmdp-runtime-max-traversal-depth-default', 'runtimeMaxTraversalDepthDefault', 'maxTraversalDepthDefault'],
      ['cmdp-runtime-max-traversal-depth-max', 'runtimeMaxTraversalDepthMax', 'maxTraversalDepthMax']
    ];
    fields.forEach(function (item) {
      if (!hasField(item[0])) return;
      next.executionLimits[item[2]] = readPositiveIntField(item[0], t(item[1]), next.executionLimits[item[2]]);
    });
    return next;
  }

  function applyAssistantConfigFields(runtimeConfig) {
    var next = normalizeRuntimeConfigForEditor(runtimeConfig);
    if (hasField('cmdp-assistant-llm-enabled')) {
      next.assistant.llm.enabled = readChecked('cmdp-assistant-llm-enabled');
      next.assistant.llm.baseUrl = readValue('cmdp-assistant-llm-base-url') || defaultRuntimeConfig().assistant.llm.baseUrl;
      next.assistant.llm.model = readValue('cmdp-assistant-llm-model') || defaultRuntimeConfig().assistant.llm.model;
    }
    if (hasField('cmdp-assistant-system-prompt')) {
      next.assistant.prompt = next.assistant.prompt || {};
      next.assistant.prompt.system = String(readValue('cmdp-assistant-system-prompt') || '').trim() || defaultRuntimeConfig().assistant.prompt.system;
      next.assistant.prompt.objectFlowSemantic = String(readValue('cmdp-assistant-object-flow-semantic-system-prompt') || '').trim() || defaultRuntimeConfig().assistant.prompt.objectFlowSemantic;
      next.assistant.prompt.objectFlow = String(readValue('cmdp-assistant-object-flow-system-prompt') || '').trim() || defaultRuntimeConfig().assistant.prompt.objectFlow;
      next.assistant.prompt.diagramInterpretation = String(readValue('cmdp-assistant-diagram-interpret-system-prompt') || '').trim() || defaultRuntimeConfig().assistant.prompt.diagramInterpretation;
      next.assistant.prompt.diagramMapping = String(readValue('cmdp-assistant-diagram-mapping-system-prompt') || '').trim() || defaultRuntimeConfig().assistant.prompt.diagramMapping;
      delete next.assistant.prompt.selection;
      delete next.assistant.prompt.matching;
    }
    if (hasField('cmdp-assistant-mcp-enabled')) {
      next.assistant.mcp.enabled = readChecked('cmdp-assistant-mcp-enabled');
      next.assistant.mcp.allowedTools = splitToolList(readValue('cmdp-assistant-mcp-tools')).length
        ? splitToolList(readValue('cmdp-assistant-mcp-tools'))
        : defaultRuntimeConfig().assistant.mcp.allowedTools.slice();
      next.assistant.mcp.maxContextBytes = readPositiveIntField('cmdp-assistant-mcp-max-context-bytes', t('assistantMcpMaxContextBytes'), next.assistant.mcp.maxContextBytes);
      next.assistant.mcp.timeoutMs = readPositiveIntField('cmdp-assistant-mcp-timeout-ms', t('assistantMcpTimeoutMs'), next.assistant.mcp.timeoutMs);
      next.assistant.mcp.maxClasses = readPositiveIntField('cmdp-assistant-mcp-max-classes', t('assistantMcpMaxClasses'), next.assistant.mcp.maxClasses);
      next.assistant.mcp.maxDomains = readPositiveIntField('cmdp-assistant-mcp-max-domains', t('assistantMcpMaxDomains'), next.assistant.mcp.maxDomains);
      next.assistant.mcp.maxRelationDomains = readPositiveIntField('cmdp-assistant-mcp-max-relation-domains', t('assistantMcpMaxRelationDomains'), next.assistant.mcp.maxRelationDomains);
      next.assistant.mcp.maxCandidateClasses = readPositiveIntField('cmdp-assistant-mcp-max-candidate-classes', t('assistantMcpMaxCandidateClasses'), next.assistant.mcp.maxCandidateClasses);
      next.assistant.semanticPlan = next.assistant.semanticPlan || {};
      next.assistant.semanticPlan.checkpointTtlSec = readPositiveIntField('cmdp-assistant-semantic-plan-checkpoint-ttl-sec', t('assistantSemanticPlanCheckpointTtlSec'), next.assistant.semanticPlan.checkpointTtlSec || 900);
      next.assistant.semanticPlan.maxReferencePathDepth = readPositiveIntField('cmdp-assistant-semantic-plan-max-reference-path-depth', t('assistantSemanticPlanMaxReferencePathDepth'), next.assistant.semanticPlan.maxReferencePathDepth || 5);
    }
    return next;
  }

  function applyRuntimeConfigFields(runtimeConfig) {
    var next = applyRuntimeCacheFields(runtimeConfig);
    next = applyRuntimeExecutionLimitFields(next);
    next = applyAssistantConfigFields(next);
    return next;
  }

  function persistRuntimeConfig(root, runtimeConfig) {
    request(apiPrefix + '/config?root=' + encodeURIComponent(root), {
      method: 'PUT',
      body: { active: true, runtimeConfig: runtimeConfig }
    }).then(function (result) {
      state.config = result.json ? result.json.config : null;
      state.message = { type: result.ok ? 'ok' : 'error', text: result.ok ? t('configSaved') : errorText(result) };
      renderDesigner();
    });
  }

  function saveConfig() {
    var root = readValue('cmdp-root') || state.root;
    state.root = root;
    var runtimeConfig = state.config && state.config.runtimeConfig ? state.config.runtimeConfig : defaultRuntimeConfig();
    try {
      runtimeConfig = applyRuntimeConfigFields(runtimeConfig);
    } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    persistRuntimeConfig(root, runtimeConfig);
  }

  function saveGeneralSettings() {
    var root = readValue('cmdp-root') || state.root;
    var runtimeConfig = state.config && state.config.runtimeConfig ? state.config.runtimeConfig : defaultRuntimeConfig();
    state.root = root;
    try {
      runtimeConfig = applyRuntimeConfigFields(runtimeConfig);
    } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    persistRuntimeConfig(root, runtimeConfig);
  }

  function refreshDesigner() {
    state.root = readValue('cmdp-root') || state.root;
    loadDesigner();
  }

  function syncCatalog() {
    state.catalogSyncing = true;
    state.catalogStatus = Object.assign({}, state.catalogStatus || {}, { state: 'syncing', error: '' });
    renderDesigner();
    request(apiPrefix + '/model/catalog?includeAttributes=true&root=' + encodeURIComponent(state.root || 'Cst_QueryTool')).then(function (result) {
      if (!result.ok || !result.json || !result.json.catalog) {
        throw new Error(errorText(result));
      }
      return writeCatalogCache(result.json.catalog).then(function (record) {
        applyCatalogCache(record);
        state.catalogSyncing = false;
        state.message = { type: 'ok', text: t('catalogReady') };
        renderDesigner();
      });
    }).catch(function (error) {
      state.catalogSyncing = false;
      state.catalogStatus = {
        state: 'error',
        updatedAt: state.catalogStatus && state.catalogStatus.updatedAt,
        error: error.message || String(error)
      };
      state.message = { type: 'error', text: t('catalogError') + ': ' + (error.message || String(error)) };
      renderDesigner();
    });
  }

  function selectClassFromCatalog(className) {
    var name = String(className || '').trim();
    var catalogClass = catalogClassByName(name);
    if (!catalogClass) return;
    state.selectedClass = catalogClass.name || name;
    state.classCheckResult = null;
    state.checkedClass = catalogClass;
    state.classAttributes = catalogClass.attributes || [];
    state.message = { type: 'ok', text: t('catalogClassApplied') };
    renderDesigner();
  }

  function selectTemplate(code) {
    state.selectedTemplate = state.templates.find(function (item) { return item.code === code; }) || null;
    state.objectGroupDraft = null;
    state.relationDraft = null;
    state.viewComposerDraft = null;
    state.paramRowsDraft = null;
    state.result = null;
    state.extractionPreview = null;
    state.extractionSource = '';
    state.checkedClass = null;
    state.classCheckResult = null;
    state.classAttributes = [];
    hydrateDesignerStateFromTemplate({ replaceRunParams: true });
    state.designerSection = 'templates';
    if (window.history && window.history.pushState) window.history.pushState({ designerSection: 'templates' }, '', designerSectionUrl('templates'));
    fetchVersions(code).then(renderDesigner);
  }

  function loadVersion(versionId) {
    var version = state.templateVersions.find(function (item) { return String(item.id) === String(versionId); });
    if (!version) return;
    var selected = state.selectedTemplate || {};
    state.selectedTemplate = {
      id: selected.id,
      code: selected.code,
      description: selected.description,
      active: selected.active !== false,
      spec: version.spec || selected.spec || defaultSpec(),
      paramsSchema: selected.paramsSchema || {},
      resultSchema: selected.resultSchema || {},
      specHash: selected.specHash
    };
    state.objectGroupDraft = null;
    state.relationDraft = null;
    state.viewComposerDraft = null;
    state.paramRowsDraft = null;
    state.extractionPreview = null;
    state.extractionSource = '';
    state.checkedClass = null;
    state.classCheckResult = null;
    state.classAttributes = [];
    hydrateDesignerStateFromTemplate({ replaceRunParams: true });
    state.message = { type: 'ok', text: t('versionLoaded') };
    state.designerSection = 'template';
    if (window.history && window.history.pushState) window.history.pushState({ designerSection: 'template' }, '', designerSectionUrl('template'));
    renderDesigner();
  }

  function checkClassByName(className) {
    var name = String(className || '').trim();
    if (!name) {
      state.message = { type: 'error', text: t('fieldRequired', { label: t('classNameInput') }) };
      renderDesigner();
      return;
    }
    request(apiPrefix + '/model/classes/' + encodeURIComponent(name)).then(function (classResult) {
      state.classCheckResult = classResult;
      state.checkedClass = classResult.ok && classResult.json ? classResult.json.class : null;
      state.selectedClass = name;
      if (!classResult.ok) {
        state.classAttributes = [];
        state.message = { type: 'error', text: errorText(classResult) };
        renderDesigner();
        return null;
      }
      return request(apiPrefix + '/model/classes/' + encodeURIComponent(name) + '/attributes').then(function (attrResult) {
        state.classAttributes = attrResult.ok && attrResult.json && attrResult.json.data ? attrResult.json.data : [];
        state.message = attrResult.ok ? { type: 'ok', text: t('classFound') } : { type: 'error', text: errorText(attrResult) };
        renderDesigner();
        return attrResult;
      });
    }).catch(function (error) {
      state.classCheckResult = { ok: false, status: 0, json: null };
      state.checkedClass = null;
      state.classAttributes = [];
      state.message = { type: 'error', text: error.message || String(error) };
      renderDesigner();
    });
  }

  function applyClassFallback() {
    var fallback = String(readValue('cmdp-class-fallback') || readValue('cmdp-class-check') || '').trim();
    if (!fallback) {
      state.message = { type: 'error', text: t('fieldRequired', { label: t('classNameFallback') }) };
      renderDesigner();
      return;
    }
    var specData;
    var spec;
    var paramsSchema;
    var resultSchema;
    try {
      specData = readSpecWithParamEditor();
      spec = specData.spec;
    } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    try {
      paramsSchema = readCurrentParamsSchema((state.selectedTemplate && state.selectedTemplate.paramsSchema) || {});
      resultSchema = readCurrentResultSchema((state.selectedTemplate && state.selectedTemplate.resultSchema) || {});
    } catch (error) {
      state.message = { type: 'error', text: error.message };
      renderDesigner();
      return;
    }
    spec.defaults = spec.defaults && typeof spec.defaults === 'object' && !Array.isArray(spec.defaults) ? spec.defaults : {};
    spec.defaults.className = fallback;
    spec.params = spec.params && typeof spec.params === 'object' && !Array.isArray(spec.params) ? spec.params : {};
    spec.params.className = Object.assign({}, spec.params.className || {}, {
      type: (spec.params.className && spec.params.className.type) || 'string',
      required: false,
      default: (spec.params.className && spec.params.className.default) || fallback,
      example: (spec.params.className && spec.params.className.example) || fallback
    });
    updateSelectedFromEditor(spec);
    state.selectedTemplate.paramsSchema = paramsSchema;
    state.selectedTemplate.resultSchema = resultSchema;
    state.runParams = Object.assign({}, specData.examples || {}, state.runParams || {});
    if (!state.runParams.className) state.runParams.className = fallback;
    state.selectedClass = fallback;
    clearDraftExecutionState({ clearExtractionSource: true });
    state.message = { type: 'ok', text: t('classFallbackApplied') };
    renderDesigner();
  }

  function buildBuilderTemplate(kind, values) {
    var attrType = values.attrType || 'reference';
    var className = values.className || 'Asset';
    var depth = values.depth || '1';
    var referenceClass = values.referenceClass || className;
    var rightType = values.rightType || 'string';
    if (kind === 'domainTraversal') {
      return {
        code: 'BuilderDomainTraversal',
        description: t('builderDomainDescription'),
        params: { attrType: attrType, className: className, depth: depth },
        spec: { version: 1, params: { attrType: { type: 'string', required: true }, className: { type: 'string', required: true }, depth: { type: 'string', required: false, default: depth } }, steps: [
          { type: 'findClassesByAttributeType', attributeTypeParam: 'attrType', as: 'classes' },
          { type: 'filterRows', from: 'classes', filters: [{ column: 'Class', op: 'equals', valueParam: 'className' }], as: 'filteredClasses' },
          { type: 'traverseDomains', from: 'filteredClasses', direction: 'both', depthParam: 'depth', as: 'domains' }
        ], result: { tables: [
          { name: 'filteredClasses', columns: ['Class', 'Description', 'Attribute', 'AttributeType'] },
          { name: 'domains', columns: ['Depth', 'Class', 'Domain', 'Source', 'Destination', 'Direction', 'RelatedClass', 'Cardinality'] }
        ] } }
      };
    }
    if (kind === 'attributeComparison') {
      return {
        code: 'BuilderAttributeComparison',
        description: t('builderComparisonDescription'),
        params: { attrType: attrType, referenceClass: referenceClass },
        spec: { version: 1, params: { attrType: { type: 'string', required: true }, referenceClass: { type: 'string', required: true } }, steps: [
          { type: 'findClassesByAttributeType', attributeTypeParam: 'attrType', as: 'classes' },
          { type: 'compareClassAttributes', from: 'classes', referenceClassParam: 'referenceClass', compareBy: ['name', 'type'], as: 'attributeComparison' }
        ], result: { tables: [{ name: 'attributeComparison', columns: ['Class', 'ComparedClass', 'CompareBy', 'CommonCount', 'ClassOnlyCount', 'ComparedClassOnlyCount', 'CommonAttributes'] }] } }
      };
    }
    if (kind === 'setOperations') {
      return {
        code: 'BuilderClassSetOperations',
        description: t('builderSetDescription'),
        params: { leftType: attrType, rightType: rightType },
        spec: { version: 1, params: { leftType: { type: 'string', required: true }, rightType: { type: 'string', required: true } }, steps: [
          { type: 'findClassesByAttributeType', attributeTypeParam: 'leftType', as: 'leftClasses' },
          { type: 'findClassesByAttributeType', attributeTypeParam: 'rightType', as: 'rightClasses' },
          { type: 'intersectRows', from: 'leftClasses', with: 'rightClasses', on: 'Class', distinct: true, as: 'classesWithBoth' },
          { type: 'joinRows', from: 'classesWithBoth', with: 'rightClasses', on: 'Class', mode: 'inner', rightPrefix: 'Right', as: 'joinedAttributes' }
        ], result: { tables: [
          { name: 'classesWithBoth', columns: ['Class', 'Description', 'Attribute', 'AttributeType'] },
          { name: 'joinedAttributes', columns: ['Class', 'Attribute', 'AttributeType', 'RightAttribute', 'RightAttributeType'] }
        ] } }
      };
    }
    return {
      code: 'BuilderClassesByAttribute',
      description: t('builderClassesDescription'),
      params: { attrType: attrType },
      spec: defaultSpec()
    };
  }

  function applyBuilder() {
    var kind = readValue('cmdp-builder-kind') || 'classes';
    var built = buildBuilderTemplate(kind, {
      attrType: readValue('cmdp-builder-attr-type') || 'reference',
      className: readValue('cmdp-builder-class-name') || state.selectedClass || 'Asset',
      depth: readValue('cmdp-builder-depth') || '1',
      referenceClass: readValue('cmdp-builder-reference-class') || state.selectedClass || 'Asset',
      rightType: readValue('cmdp-builder-right-type') || 'string'
    });
    invalidateAssistantObjectFlowRequests();
    invalidateAssistantPromptAutosave();
    state.selectedTemplate = {
      code: readTemplateCode() || built.code,
      description: built.description,
      active: true,
      spec: built.spec,
      paramsSchema: {},
      resultSchema: {}
    };
    state.builderKind = kind;
    state.runParams = built.params;
    state.selectedClass = built.params.className || built.params.referenceClass || state.selectedClass;
    state.objectGroupDraft = null;
    state.relationDraft = null;
    state.viewComposerDraft = null;
    state.paramRowsDraft = null;
    state.checkedClass = null;
    state.classCheckResult = null;
    state.classAttributes = [];
    state.message = { type: 'ok', text: t('builderApplied') };
    renderDesigner();
  }

  function applyTemplateCopySource(code) {
    var sourceCode = String(code || '').trim();
    var selected = state.selectedTemplate || emptyTemplate();
    var currentCode = readTemplateCode(selected);
    var currentDescription = readTemplateDescription(selected, currentCode);
    var currentActive = readTemplateActive(selected);
    if (!sourceCode) {
      state.selectedTemplate = Object.assign({}, selected, {
        code: currentCode || selected.code || '',
        description: currentDescription || selected.description || '',
        active: currentActive,
        copySourceCode: ''
      });
      renderDesigner();
      return;
    }
    var source = state.templates.find(function (item) { return item.code === sourceCode; });
    if (!source) {
      state.message = { type: 'error', text: t('noTemplateToCopy') };
      renderDesigner();
      return;
    }
    state.selectedTemplate = {
      code: currentCode || '',
      description: currentDescription || '',
      active: currentActive,
      spec: cloneJsonValue(source.spec, defaultSpec()),
      paramsSchema: cloneJsonValue(source.paramsSchema, {}),
      resultSchema: cloneJsonValue(source.resultSchema, {}),
      copySourceCode: source.code
    };
    state.templateVersions = [];
    state.runParams = {};
    state.objectGroupDraft = null;
    state.relationDraft = null;
    state.viewComposerDraft = null;
    state.paramRowsDraft = null;
    state.extractionPreview = null;
    state.extractionSource = '';
    state.result = null;
    state.checkedClass = null;
    state.classCheckResult = null;
    state.classAttributes = [];
    hydrateDesignerStateFromTemplate({ replaceRunParams: true });
    state.message = { type: 'ok', text: t('templateCopyApplied', { code: source.code }) };
    renderDesigner();
  }

